"""Measure source ink removal feasibility without changing any candidate or threshold."""
import pathlib,json,numpy as np,pypdfium2 as pdfium
from PIL import Image
R=pathlib.Path('/data/coding/scanweave/qualification/acr06');E=R/'hvc41d';L=R/'local/hvc41d';rows=json.loads((E/'p1-preflight-ledger.json').read_text());src=np.asarray(Image.open(R/'local/ink33r/renders/historical/01-source.png').convert('RGB'));lum=src.astype(float)@np.array([.2126,.7152,.0722]);d=pdfium.PdfDocument(str(R/'local/ink33r/historical.pdf'));pg=d[0];base=np.asarray(pg.render(scale=300/72,rev_byteorder=True).to_pil().convert('RGB')).copy();pg.close();d.close();dl=pdfium.PdfDocument(str(L/'p1-font-diagnostic.pdf'));pg=dl[0];font=np.asarray(pg.render(scale=300/72,rev_byteorder=True,fill_color=(255,255,255,255)).to_pil().convert('RGB')).copy();pg.close();dl.close();out=[]
for r in rows:
 if r['outcome']!='requires_visual_review':continue
 a,b,c,d=r['reference_box'];paper=r['admission']['paper_luma'];ink=r['source_ink_luma'];ref=lum[b:d,a:c]<(paper+ink)/2;bl=base[b:d,a:c].astype(float)@np.array([.2126,.7152,.0722]);fl=font[b:d,a:c].astype(float)@np.array([.2126,.7152,.0722]);inkvec=np.array(r['fill_rgb'])@np.array([.2126,.7152,.0722]);fm=fl<(255+inkvec)/2;bdark=bl<(paper+ink)/2;overlap=fm&bdark&~ref;out.append({'proposal':r['proposal'],'symbol':r['ocr_unverified'],'reference_pixels':int(ref.sum()),'font_mask_pixels':int(fm.sum()),'baseline_dark_unpatched_within_glyph':int(overlap.sum()),'baseline_dark_outside_reference':int((bdark&~ref).sum())})
(E/'p1-residual-diagnostic.json').write_text(json.dumps(out,indent=2)+'\n');print('zero residual',sum(x['baseline_dark_unpatched_within_glyph']==0 for x in out),'/',len(out));print('smallest',sorted(out,key=lambda x:x['baseline_dark_unpatched_within_glyph'])[:15])
